UPDATE dataset_file SET is_deleted = TRUE, updated_at = #{updatedAt}, updated_by = #{updatedBy}
WHERE file_id = #{fileId} AND dataset_id = #{datasetId} AND is_deleted = FALSE
  AND EXISTS (SELECT 1 FROM dataset WHERE dataset.dataset_id = #{datasetId} AND )


UPDATE dataset_file SET description = #{description,jdbcType=VARCHAR}, updated_at = #{updatedAt}, updated_by = #{updatedBy}
WHERE file_id = #{fileId} AND dataset_id = #{datasetId} AND is_deleted = FALSE
  AND EXISTS (SELECT 1 FROM dataset WHERE dataset.dataset_id = #{datasetId} AND )
